TOC.FLDID30, TOC.FLDTAG30, TOC.FLDTAGA30, GENHTAB_30.FLDTAB AS FLDTAB30, GENHTAB_30.FLDCOM AS FLDCOM30, GENHTAB_30.FLDCOMA AS FLDCOMA30, GENHTAB_30.FLDDFORMAT AS FLDDFORMAT30, GENHTAB_30.FLDIFORMAT AS FLDIFORMAT30, GENHTAB_30.FLDTYPE AS FLDTYPE30, GENHTAB_30.SUBLINKF AS SUBLINKF30,  GENHTAB_30.FLDSEARCH AS FLDSEARCH30, GENHTAB_30.FLDCRITERIA AS FLDCRITERIA30, GENHTAB_30.FLDCHGINF as FLDCHGINF30, GENHTAB_30.FLDLOWER as FLDLOWER30, GENHTAB_30.FLDUPPER as FLDUPPER30, GENHTAB_30.FLDREGEX as FLDREGEX30
FROM         
TOC         
LEFT OUTER JOIN GENHTAB as GENHTAB_16 ON TOC.FLDID16 = GENHTAB_16.FLDID         
LEFT OUTER JOIN GENHTAB as GENHTAB_17 ON TOC.FLDID17 = GENHTAB_17.FLDID         
LEFT OUTER JOIN GENHTAB as GENHTAB_18 ON TOC.FLDID18 = GENHTAB_18.FLDID         
LEFT OUTER JOIN GENHTAB as GENHTAB_19 ON TOC.FLDID19 = GENHTAB_19.FLDID         
