LEFT OUTER JOIN GENHTAB as GENHTAB_21 ON TOC.FLDID21 = GENHTAB_21.FLDID         
LEFT OUTER JOIN GENHTAB as GENHTAB_22 ON TOC.FLDID22 = GENHTAB_22.FLDID         
LEFT OUTER JOIN GENHTAB as GENHTAB_23 ON TOC.FLDID23 = GENHTAB_23.FLDID         
LEFT OUTER JOIN GENHTAB as GENHTAB_24 ON TOC.FLDID24 = GENHTAB_24.FLDID         
LEFT OUTER JOIN GENHTAB as GENHTAB_25 ON TOC.FLDID25 = GENHTAB_25.FLDID         
LEFT OUTER JOIN GENHTAB as GENHTAB_26 ON TOC.FLDID26 = GENHTAB_26.FLDID         
